import {WEATHER} from './weather.js?v=landscape13';
import * as T from './three.module.js';import {daylight,namibiaTime} from './namibia-time.js?v=life17';
export function installDayNight({scene,sun,fillLight,mobile=false}){scene.add(sun.target);let timer=1,scan=0,sample=daylight(),time=namibiaTime();const pools=Array.from({length:mobile?1:2},()=>{const light=new T.PointLight('#ffcf86',0,18,2);light.castShadow=false;scene.add(light);return light;}),nightTop=new T.Color('#071426'),nightFog=new T.Color('#162a3a'),lamps=[],materials=new Set();
 function collect(){scene.traverse(o=>{if(o.isMesh){for(const m of Array.isArray(o.material)?o.material:[o.material]){if(m.isMeshStandardMaterial&&(m.userData.nightWindow||['a8c4c5','a4c6c7','99b8b6'].includes(m.color?.getHexString())||/lightwhite|lantern/i.test(m.name||'')))materials.add(m);}}});}
 function addLamp(x,z,y=3.8){const root=new T.Group(),pole=new T.Mesh(new T.CylinderGeometry(.06,.09,y,6),new T.MeshStandardMaterial({color:'#56695e',roughness:.9})),bulb=new T.Mesh(new T.SphereGeometry(.17,8,6),new T.MeshStandardMaterial({color:'#ffe8ab',emissive:'#ffc66d',emissiveIntensity:0}));pole.position.set(x,y/2,z);bulb.position.set(x,y,z);root.add(pole,bulb);scene.add(root);lamps.push({x,z,y,bulb});}
 for(const [x,z]of [[-3,8],[3,-6],[-29,27],[-23,32],[-80,25],[-82,0],[73,35],[0,87],[2,98]])addLamp(x,z);
 collect();return {lamps,pools,get sample(){return sample;},update(dt,focus,sky,now=Date.now()){timer+=dt;scan+=dt;if(timer>=1){timer=0;sample=daylight(now);time=namibiaTime(now);const badge=document.querySelector('#clock-status');if(badge)badge.textContent=time.label+' · '+sample.phase;if(scan>8){collect();scan=0;}}
 const light=sample.light,weather=WEATHER[sky?.type],hemi=scene.children.find(o=>o.isHemisphereLight);sun.intensity=(weather?.sun??2.4)*(.035+.965*light);sun.target.position.set(focus.x,0,focus.z);sun.position.set(focus.x+Math.sin(sample.azimuth)*60,Math.max(4,Math.sin(sample.altitude*Math.PI/180)*70),focus.z+Math.cos(sample.azimuth)*50);sun.color.set(light<.2?'#b2c8e3':'#fff0cf');if(hemi)hemi.intensity=(weather?.ambient??1.65)*(.18+.82*light);if(fillLight)fillLight.intensity=.10+.48*light;scene.environmentIntensity=.12+.88*light;
 const uniforms=sky?.sky?.material?.uniforms;if(uniforms){uniforms.top.value.lerp(nightTop,1-light);uniforms.horizon.value.lerp(nightFog,(1-light)*.92);}if(scene.fog)scene.fog.color.lerp(nightFog,(1-light)*.9);if(sky?.clouds)sky.clouds.material.opacity*=.2+.8*light;
 for(const lamp of lamps)lamp.bulb.material.emissiveIntensity=sample.lamps*1.6;for(const mat of materials){mat.emissive?.set('#ffd292');mat.emissiveIntensity=sample.lamps*(mat.userData.nightWindow ? .8 : 1.2);}
 const nearest=lamps.filter(l=>Math.hypot(l.x-focus.x,l.z-focus.z)<26).sort((a,b)=>Math.hypot(a.x-focus.x,a.z-focus.z)-Math.hypot(b.x-focus.x,b.z-focus.z));pools.forEach((l,i)=>{const p=nearest[i];l.intensity=p?sample.lamps*8:0;if(p)l.position.set(p.x,p.y,p.z);});}};
}
